import{_ as e,o as i,f as l,a6 as t}from"./chunks/framework.BFhbG0o2.js";const p=JSON.parse('{"title":"德国水处理展会视觉体系","description":"从主视觉、展位到宣传资料的跨媒介统一与远程落地协作案例。","frontmatter":{"title":"德国水处理展会视觉体系","description":"从主视觉、展位到宣传资料的跨媒介统一与远程落地协作案例。","pageClass":"page-case-detail","status":"published"},"headers":[],"relativePath":"portfolio/exhibition-visual.md","filePath":"portfolio/exhibition-visual.md"}'),o={name:"portfolio/exhibition-visual.md"};function r(h,a,s,n,c,d){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="德国水处理展会视觉体系" tabindex="-1">德国水处理展会视觉体系 <a class="header-anchor" href="#德国水处理展会视觉体系" aria-label="Permalink to &quot;德国水处理展会视觉体系&quot;">​</a></h1><blockquote><p>一个跨媒介、跨地区落地的展会视觉项目。客户信息与部分业务细节已脱敏。</p></blockquote><h2 id="背景与目标" tabindex="-1">背景与目标 <a class="header-anchor" href="#背景与目标" aria-label="Permalink to &quot;背景与目标&quot;">​</a></h2><p>企业参加德国国际水处理技术展，需要在有限的展位空间内建立专业、统一且易识别的品牌印象，并保证展位、宣传册和现场物料在不同供应商之间保持一致。</p><h2 id="我的角色" tabindex="-1">我的角色 <a class="header-anchor" href="#我的角色" aria-label="Permalink to &quot;我的角色&quot;">​</a></h2><p>担任主创设计师，负责主视觉、展位视觉、宣传资料和落地规范，并远程协调当地搭建团队处理色彩、材质与尺寸差异。</p><h2 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h2><ul><li>同一套信息需要适配展位、印刷物和现场导视。</li><li>远程协作增加了色差、材质替换和文件版本失控的风险。</li><li>展会现场阅读距离变化大，信息必须有清晰优先级。</li></ul><h2 id="工作方法" tabindex="-1">工作方法 <a class="header-anchor" href="#工作方法" aria-label="Permalink to &quot;工作方法&quot;">​</a></h2><ol><li>先建立唯一的核心信息与主视觉规则。</li><li>按“远距离识别—中距离理解—近距离获取资料”拆分内容层级。</li><li>为关键物料建立尺寸、色彩、出血和替代材质说明。</li><li>所有修改通过统一版本记录回收，避免供应商各自保留不同文件。</li><li>项目结束后将版式、制作参数和问题记录沉淀为下次展会资产。</li></ol><h2 id="结果与复盘" tabindex="-1">结果与复盘 <a class="header-anchor" href="#结果与复盘" aria-label="Permalink to &quot;结果与复盘&quot;">​</a></h2><p>根据项目记录，现场收集高质量线索 500 余条，并直接促成约 200 万元订单。视觉系统的重要价值不仅是现场效果，也在于让跨团队交付变得可检查、可追踪。</p><h2 id="继续探索" tabindex="-1">继续探索 <a class="header-anchor" href="#继续探索" aria-label="Permalink to &quot;继续探索&quot;">​</a></h2><ul><li><a href="/aigc/commercial-visual-system.html">AI 商业视觉生产系统</a></li><li><a href="/resources/notion.html">AI 项目复盘清单</a></li><li><a href="/blog/personal-resource-library.html">个人资源库比普通博客更重要</a></li></ul><p><a href="/portfolio/">← 返回案例库</a></p>',15)])])}const f=e(o,[["render",r]]);export{p as __pageData,f as default};
